protocol Meas {
  roles C, A, J;
  rec Loop measure n bound 5 {
    A -> J : Draft(answer: Str, cost: Int) [cost <= budget] uses search oracle;
    choice at J -> C {
      Accept: { J -> A : Done(); }
      Reject(reason: Str) [len(reason) > 0]: { J -> A : Retry(); continue Loop; }
    }
  }
}

// =============================================================================
// async_fanin_bad.casl — REJECTED: reorder trap on fan-in (LH-F-010)
// =============================================================================
// C asks A and B and expects the responses in the order A, then B —
// but both write into C's ONE inbox, and B may answer first. Then
// B's `ResB` sits at the inbox head, yet C expects `ResA` from A → C is blocked, no
// reordering → DEADLOCK. Exactly the trap that async introduces: responses do
// NOT come back in request order, guaranteed.
//
// Synchronously this protocol would be well-formed — the async gate rejects it
// (deny-by-default) because ONE interleaving deadlocks. Remedy: keep it synchronous,
// or restructure so that C accepts both orderings.
//
//   ./casl check examples/async_fanin_bad.casl   # ✗ async-rejected (reorder/deadlock)
// =============================================================================
protocol AsyncFaninBad {
  roles C, A, B;
  async k 2;

  C -> A : Req();
  C -> B : Req();
  A -> C : ResA();
  B -> C : ResB();
}

// =============================================================================
// async_fanout.casl — true concurrency via buffers (LH-F-010), SAFE
// =============================================================================
// C distributes two tasks to independent workers A and B; the responses go to
// DISJOINT receivers (C and E, respectively). Because each inbox has only ONE
// sender, there is no ordering contention — no matter what order the responses
// arrive in, no inbox head is ever wrongly expected.
//
// Truly async: up to 2 messages in flight at a time ⇒ NOT sync-equivalent,
// but the deny-by-default gate certifies bounded + orphan-free + deadlock-free
// ⇒ class `async-bounded-safe`.
//
//   ./casl check examples/async_fanout.casl      # ✓ async-bounded-safe
// =============================================================================
protocol AsyncFanout {
  roles C, A, B, E;
  async k 1;

  C -> A : task();
  C -> B : task();
  A -> C : done();
  B -> E : done();
}

// =============================================================================
// async_request.casl — buffered request/response (LH-F-010), SYNC-EQUIVALENT
// =============================================================================
// The `async` marker adds the buffered refinement (opt-in). Without the
// marker the protocol would stay synchronous (the proven default). Here only ONE
// message is in flight at a time ⇒ the async behavior coincides with the
// synchronous semantics ⇒ class `async-synchronizable` (inherits the proven guarantees).
//
//   ./casl check examples/async_request.casl     # ✓ async-synchronizable
// =============================================================================
protocol AsyncRequest {
  roles C, A;
  async k 1;

  C -> A : Req();
  A -> C : Res();
}

// =============================================================================
// auto_reply_unsafe.casl — ANTI-PATTERN (MUST be rejected)
// =============================================================================
// The classic agent blunder: an auto-responder that sends UNPROMPTED on every
// mail. `Deliver` is effect-bearing (uses send, mode write) and
// does NOT lie behind an approval gate → approval dominance (LH-Q-011) MUST
// make `casl check` reject with exit 1. Exactly this default mistake is what
// CASL structurally prevents (deny-by-default), instead of waving it through.
//
//   ./casl check examples/auto_reply_unsafe.casl    # expected: ✗ REJECTED (exit 1)
// =============================================================================
protocol AutoReplyUnsafe {
  roles Env, S, M;
  env Env;
  agent S caps { send(to) scope "mail:send" mode write ttl 1 sig "s1"; }

  stream Loop {
    choice at Env -> S {
      Mail(subject: Str): {
        S -> M : Deliver() uses send irreversible;
        continue Loop;
      }
      Quit: { S -> M : Closed(); }
    }
  }
}

// Canonical CASL example — parses exactly to casl_core.G_OK
protocol BudgetedQA {
  roles C, A, J;
  agent A caps { search(query) scope "web:readonly" mode read ttl 3 sig "sig-A1"; }
  crash A;

  C -> A : Request(question: Str, budget: Int);
  rec Loop {
    A -> J : Draft(answer: Str, cost: Int) [cost <= budget] uses search oracle;
    choice at J -> C {
      Accept: { J -> A : Done(); }
      Reject(reason: Str) [len(reason) > 0]: { J -> A : Retry(); continue Loop; }
    }
  }
}

// Termination-annotated variant — parses exactly to casl_core.G_OK_TERM
// (ranking measure budget with upper bound 3 → loop terminates, ttl-safe).
protocol BudgetedQA {
  roles C, A, J;
  agent A caps { search(query) scope "web:readonly" mode read ttl 3 sig "sig-A1"; }
  crash A;

  C -> A : Request(question: Str, budget: Int);
  rec Loop measure budget bound 3 {
    A -> J : Draft(answer: Str, cost: Int) [cost <= budget] uses search oracle;
    choice at J -> C {
      Accept: { J -> A : Done(); }
      Reject(reason: Str) [len(reason) > 0]: { J -> A : Retry(); continue Loop; }
    }
  }
}

// =============================================================================
// calendar_guard.casl — refuse to confirm an already-booked slot (case study)
// See docs/cookbook/email-secretary.md
// =============================================================================
// U = User, S = secretary agent, K = calendar.
//
// An email committed to a date. S looks up the calendar and reports the number of
// CONFLICTS for the requested slot (monitored `oracle` boundary over the calendar
// read). The data contract [conflicts <= 0] is the DOUBLE-BOOKING GUARD: the flow
// only stays well-formed when the slot is free (conflicts == 0). The irreversible
// booking (uses calendar, mode write) additionally sits behind an approval gate.
// K receives a distinguishing label on both paths (Reserve / Pass) → realizable.
//
//   ./casl check examples/calendar_guard.casl
//   ./casl run   examples/calendar_guard.casl --approve
// =============================================================================
protocol CalendarGuard {
  roles U, S, K;
  agent S caps {
    lookup(range)   scope "cal:readonly" mode read  ttl 1 sig "s0";
    calendar(event) scope "cal:write"    mode write ttl 1 sig "s1";
  }

  U -> S : Commit(detail: Str);
  S -> U : Slot(conflicts: Int) [conflicts <= 0] uses lookup oracle;
  choice approval at U -> S {
    Book consent: { S -> K : Reserve() uses calendar irreversible; }
    Hold:         { S -> K : Pass(); }
  }
}

