// =============================================================================
// casl_ide_pipeline.casl — the IDE describes ITSELF (Phase 5, P0/"lived system")
// =============================================================================
// The requirement-driven IDE is itself a pipeline of exactly the node kinds
// it knows — and it passes its OWN gate:
//
//   U  user (Requirements = authority)           G  generator oracle (LLM box)
//   V  verifier (deterministic checker)          R  reviewer oracle (LLM box, Tier 2)
//   H  human (Tier 3)                            Store  project (irreversible adoption)
//
//   · G→V:Candidate  ⟨oracle⟩ [len(casl)>0]  — generator = opaque box, monitored at the boundary.
//   · V→R:Verdict    ⟨verified⟩              — the checker is the verified program (hull).
//   · R→H:Review     ⟨oracle⟩ [len(note)>0]  — reviewer = opaque box, monitored.
//   · Store→U:Adopted ⟨irreversible⟩ behind the `approval` gate (H) — adoption only with attestation.
//
// `casl check` accepts this (pipeline-safe + approval-dominated). The IDE's monotone gate
// requires human attestation for the verified node AND the irreversible adoption
// (Tier 3) — so the IDE checks itself with its own means.
//
//   ./casl check examples/casl_ide_pipeline.casl     # ✓ accepted
// =============================================================================
protocol CaslIdePipeline {
  roles U, G, V, R, H, Store;
  agent Store caps { write(artifact) scope "project:artifacts" mode write ttl 1 sig "store1"; }

  U -> G : Requirement(spec: Str);
  G -> V : Candidate(casl: Str) [len(casl) > 0] oracle;
  V -> R : Verdict(ok: Bool) verified;
  R -> H : Review(note: Str) [len(note) > 0] oracle;
  choice approval at H -> Store {
    Attest consent: { Store -> U : Adopted() uses write irreversible; }
    Reject:         { Store -> U : Rejected(); }
  }
}

// =============================================================================
// concurrent.casl — true concurrency (LH-Q-001d), certified
// =============================================================================
// Two role-DISJOINT communications: P→Q and R→S share no role, so they are
// independent and commute (diamond/confluence). Written sequentially,
// but the endpoints may execute them in any order.
//
// `casl check` accepts this only because the global semantics (with the swap rule)
// fully captures this concurrent behavior ('certified'). Concurrency that
// the (soundly under-approximating) global semantics does not capture would be rejected —
// deny-by-default, when in doubt, check.
//
//   ./casl check examples/concurrent.casl     # ✓ accepted (4 roles, concurrent)
// =============================================================================
protocol Concurrent {
  roles P, Q, R, S;

  P -> Q : Ping();
  R -> S : Log();
}

// =============================================================================
// email_assistant.casl — email assistant as an EVENT STREAM (4 roles)
// =============================================================================
// Env = inbox (external source), S = assistant (agent/ORACLE),
// U = User, M = mail connector.
//
// For each incoming mail, S drafts a reply via LLM (compose capability,
// mode read → pure text generation is NOT effect-bearing; the Contract
// [size <= cap] bounds the length). The SEND, by contrast, is irreversible
// (uses send, mode write) and lies in the consent branch of an approval gate.
// The `stream` runs deliberately unbounded, but every handler terminates.
//
// Note: the draft here is pure tool use (uses compose), NOT an `oracle`
// promise. Reason: an oracle promise must be resolved EXACTLY ONCE per loop
// iteration (promise linearity); in the Quit branch, however, nothing is
// drafted → 0 times. The monitored oracle boundary is shown by summarize/budgeted_qa.
//
//   ./casl check examples/email_assistant.casl
//   ./casl run   examples/email_assistant.casl --approve
// =============================================================================
protocol EmailAssistant {
  roles Env, S, U, M;
  env Env;
  agent S caps {
    compose(prompt) scope "llm:compose" mode read  ttl 1 sig "s0";
    send(to)        scope "mail:send"   mode write ttl 1 sig "s1";
  }

  stream Loop {
    choice at Env -> S {
      Mail(subject: Str, cap: Int): {
        S -> U : Draft(text: Str, size: Int) [size <= cap] uses compose;
        choice approval at U -> S {
          Send consent: { S -> M : Deliver() uses send irreversible; continue Loop; }
          Skip:         { S -> M : Archive();                        continue Loop; }
        }
      }
      Quit: {
        S -> U : Bye();
        S -> M : Closed();
      }
    }
  }
}

// =============================================================================
// email_secretary_reply.casl — the FOUR-BUTTON reply flow (case study)
// See docs/cookbook/email-secretary.md
// =============================================================================
// U = User, S = secretary agent (LLM-backed), M = mail connector.
//
// S summarizes the incoming mail (monitored `oracle` boundary, bounded by [len <= cap]).
// Then U presses ONE of four buttons (a `choice at U -> S`):
//   Reject  — no reply, just file the mail away.
//   Accept  — LLM drafts an acceptance; the SEND is irreversible → approval gate.
//   Analyze — LLM analyzes the work, measures it against standards, drafts a SHORT
//             reply; the SEND is irreversible → approval gate.
//   Direct  — LLM drafts a direct reply; the SEND is irreversible → approval gate.
//
// Safety: every effect-bearing SEND (uses send, mode write) is irreversible and
// sits in the `consent` branch of an approval gate (LH-Q-011). M (mail connector)
// receives a distinguishing label on every path (FileAway / Deliver / Keep) → realizable.
//
//   ./casl check examples/email_secretary_reply.casl
//   ./casl run   examples/email_secretary_reply.casl --approve
// =============================================================================
protocol EmailSecretaryReply {
  roles U, S, M;
  agent S caps {
    inspect(mail)   scope "mail:readonly" mode read  ttl 1 sig "s0";
    compose(prompt) scope "llm:compose"   mode read  ttl 1 sig "s1";
    send(to)        scope "mail:send"     mode write ttl 1 sig "s2";
  }

  M -> S : Arrived(subject: Str, cap: Int);
  S -> U : Brief(summary: Str, size: Int) [size <= cap] uses inspect oracle;
  choice at U -> S {
    Reject: {
      S -> M : FileAway();
    }
    Accept: {
      S -> U : Draft(text: Str, size: Int) [size <= cap] uses compose;
      choice approval at U -> S {
        Send consent: { S -> M : Deliver() uses send irreversible; }
        Hold:         { S -> M : Keep(); }
      }
    }
    Analyze: {
      S -> U : Short(text: Str, size: Int) [size <= cap] uses compose;
      choice approval at U -> S {
        Send consent: { S -> M : Deliver() uses send irreversible; }
        Hold:         { S -> M : Keep(); }
      }
    }
    Direct: {
      S -> U : Reply(text: Str, size: Int) [size <= cap] uses compose;
      choice approval at U -> S {
        Send consent: { S -> M : Deliver() uses send irreversible; }
        Hold:         { S -> M : Keep(); }
      }
    }
  }
}

// =============================================================================
// expense_approval.casl — expense approval (3 roles, classic business flow)
// =============================================================================
// A = assistant (agent/ORACLE), U = User/approver, L = Ledger (accounting system).
//
// Flow:
//   1. U submits a receipt and states a limit.
//   2. A reads the receipt (read capability, NOT effect-bearing) and extracts
//      the amount via LLM. The data Contract [amount <= limit] MUST hold.
//   3. The BOOKING is irreversible (uses ledger, mode write) and therefore lies
//      in the consent branch of an approval gate. L sees in BOTH branches a
//      distinguishing label (Book/Discard) → projectable.
//
//   ./casl check examples/expense_approval.casl
//   ./casl run   examples/expense_approval.casl --approve
// =============================================================================
protocol ExpenseApproval {
  roles U, A, L;
  agent A caps {
    read(receipt)  scope "doc:readonly"  mode read  ttl 1 sig "a0";
    ledger(entry)  scope "ledger:write"  mode write ttl 1 sig "a1";
  }

  U -> A : Submit(receipt: Str, limit: Int);
  A -> U : Claim(amount: Int) [amount <= limit] uses read oracle;
  choice approval at U -> A {
    Approve consent: { A -> L : Book() uses ledger irreversible; }
    Deny:            { A -> L : Discard(); }
  }
}

// =============================================================================
// inbox.casl — inbox as an EVENT STREAM (LH-F-009), target-picture slice
// =============================================================================
// Env = environment (external event source: new mail / quit), S = secretary,
// U = User, M = mail connector.
//
// The `stream` loop runs DELIBERATELY unbounded (an inbox does not end on its
// own) — but EVERY handler is finite and certified: the irreversible
// send (uses mail) lies behind an approval gate (LH-Q-011), and every role
// learns in every branch via a message from S which case applies (realizable).
//
//   ./casl check examples/inbox.casl              # ✓ accepted (stream, 4 roles)
//   ./casl run   examples/inbox.casl --approve    # one event handled per iteration
// =============================================================================
protocol Inbox {
  roles Env, S, U, M;
  env Env;
  agent S caps { mail(to) scope "mail:send" mode write ttl 1 sig "s1"; }

  stream Loop {
    choice at Env -> S {
      Mail(subject: Str): {
        S -> U : Notice(detail: Str);
        choice approval at U -> S {
          Approve consent: { S -> M : Send() uses mail; continue Loop; }
          Deny:            { S -> M : Drop(); continue Loop; }
        }
      }
      Quit: {
        S -> U : Bye();
        S -> M : Closed();
      }
    }
  }
}

// =============================================================================
// meeting_scheduler.casl — appointment finding with a retry loop + approval (3 roles)
// =============================================================================
// U = User, S = secretary (agent/ORACLE), K = calendar.
//
// S proposes a slot via LLM (plan capability, mode read) with Contract
// [cost <= budget]. U accepts or rejects with a reason → new round
// (rec with termination measure `measure maxTries bound 3`). In the Accept branch,
// the irreversible calendar booking lies behind an approval gate.
//
// Note: CASL allows NO statement AFTER a `rec` block. The booking
// must therefore be IN the Accept branch (not behind the loop). So that K
// (calendar) can distinguish the loop outcome, it receives in EVERY
// branch a message: Reserve/Pass (Accept) or Searching (Reject).
//
//   ./casl check examples/meeting_scheduler.casl
//   ./casl run   examples/meeting_scheduler.casl --approve
// =============================================================================
protocol MeetingScheduler {
  roles U, S, K;
  agent S caps {
    plan(constraint) scope "cal:read"  mode read  ttl 3 sig "s0";
    calendar(event)  scope "cal:write" mode write ttl 1 sig "s1";
  }

  U -> S : Request(constraint: Str, budget: Int, maxTries: Int);
  rec Loop measure maxTries bound 3 {
    S -> U : Propose(slot: Str, cost: Int) [cost <= budget] uses plan oracle;
    choice at U -> S {
      Accept: {
        choice approval at U -> S {
          Book consent: { S -> K : Reserve() uses calendar irreversible; }
          Hold:         { S -> K : Pass(); }
        }
      }
      Reject(reason: Str) [len(reason) > 0]: {
        S -> K : Searching();
        U -> S : Retry(maxTries: Int);
        continue Loop;
      }
    }
  }
}

// INTENTIONALLY FAULTY — demonstration of the well-formedness diagnostics.
// J decides the choice toward C. In the Accept branch A learns nothing, in the
// Reject branch A receives `Retry`. A cannot distinguish the branches locally
// (non-local choice) → not projectable (MUST).
// `casl check` MUST reject with exit 1.
protocol NonProjectable {
  roles C, A, J;

  C -> A : Request(question: Str, budget: Int);
  A -> J : Draft(answer: Str, cost: Int);
  choice at J -> C {
    Accept: { }
    Reject(reason: Str): { J -> A : Retry(); }
  }
}

// =============================================================================
// pipeline_mixed.casl — pipeline of two node kinds (LH-F-011, CASL-IDE Phase 4)
// =============================================================================
// A small pipeline: U gives a task, P is a VERIFIED (deterministic)
// program that prepares the input, Q is an LLM BOX whose response is checked
// against a Contract at the monitored boundary.
//
//   · P→Q:Prepared  ⟨verified⟩  — producer is a verified program (inside the hull).
//   · Q→U:Answer     ⟨oracle⟩ [cost <= 100] — opaque LLM box, WITH a Contract (monitored boundary).
//
// `casl check` accepts this (pipeline-safe: oracle monitored, oracle⊕verified exclusive).
// In the IDE the `verified` node additionally requires HUMAN attestation (Tier 3) —
// the machine cannot prove an arbitrary external program (W17).
//
//   ./casl check examples/pipeline_mixed.casl     # ✓ accepted
// =============================================================================
protocol PipelineMixed {
  roles U, P, Q;
  agent Q caps { llm(prompt) scope "gen" mode read ttl 1 sig "q1"; }

  U -> P : Task(spec: Str);
  P -> Q : Prepared(data: Str) verified;
  Q -> U : Answer(text: Str, cost: Int) [cost <= 100] uses llm oracle;
}

// Appointment rescheduling with an approval gate (LH-Q-011).
// The irreversible calendar action `Move` sits behind the `approval` gate (U decides),
// only in the Approve branch. K (calendar) learns a distinguishing label in BOTH branches
// (Move/Skip) → projectable. `casl check` → accepted.
protocol Reschedule {
  roles S, U, K;
  agent S caps { calendar(event) scope "cal:write" ttl 1 sig "s1"; }

  S -> U : Conflict(detail: Str);
  choice approval at U -> S {
    Approve consent: { S -> K : Move() uses calendar irreversible; }
    Deny:            { S -> K : Skip(); }
  }
}

// INTENTIONALLY FAULTY — demonstration of the approval invariant (LH-Q-011).
// The irreversible `Move` (change the calendar) happens WITHOUT a preceding approval gate.
// `casl check` MUST reject with exit 1 (approval dominance violated).
protocol RescheduleBad {
  roles S, U, K;
  agent S caps { calendar(event) scope "cal:write" ttl 1 sig "s1"; }

  S -> U : Conflict(detail: Str);
  S -> K : Move() uses calendar irreversible;
}

// =============================================================================
// secretariat.casl — FOUR roles (target-picture slice, VISION §6)
// =============================================================================
// U = User, S = secretary (agent/oracle), K = calendar, M = mail.
// Shows that CASL is expressible beyond the 3-role head fragment:
// projection/merge/realizability are parametric over the role set.
//
// Safety applies as before: the irreversible rescheduling (Move, uses calendar)
// and the mail send (Notify, uses mail) lie in the consent branch of an
// approval gate (LH-Q-011). Realizable: in BOTH branches the
// bystanders K and M each receive a distinguishing message from S (mergeable).
//
//   ./casl check examples/secretariat.casl          # ✓ accepted (4 roles)
//   ./casl run   examples/secretariat.casl --approve # consent branch runs
// =============================================================================
protocol Secretariat {
  roles U, S, K, M;
  agent S caps {
    calendar(event) scope "cal:write" mode write ttl 1 sig "s1";
    mail(to) scope "mail:send" mode write ttl 1 sig "s2";
  }

  U -> S : Conflict(detail: Str);
  choice approval at U -> S {
    Approve consent: {
      S -> K : Move() uses calendar irreversible;
      S -> M : Notify() uses mail;
      M -> U : Done();
    }
    Deny: {
      S -> K : Keep();
      S -> M : Hold();
      M -> U : Done();
    }
  }
}

// =============================================================================
// summarize.casl — Tutorial: "budgeted summarization with a check loop"
// =============================================================================
// Three participants (roles):
//   U = User        — poses the task
//   S = Summarizer  — the LLM-backed agent (the ORACLE); summarizes
//   G = Gate        — checks the result and decides
//
// Flow:
//   1. U tasks S with a text and a `budget` (max. allowed size).
//   2. S generates via LLM a summary of size `size`.
//      The data Contract [size <= budget] MUST hold — otherwise blame on S.
//   3. G decides:
//        Ok        → fits; S receives Take(); the protocol ends.
//        Trim(why) → too large; S receives Again() and repeats (loop).
//
// CASL proves the "hull" statically (projection, types, least-privilege,
// promise linearity); only the LLM output is the nondeterministic
// oracle monitored at RUNTIME (guiding principle: hull proven, LLM = oracle).
//
// Try it:
//   ./casl check examples/summarize.casl
//   ./casl run   examples/summarize.casl --budget 50            # Mock (deterministic)
//   ./casl run   examples/summarize.casl --live --budget 200    # real Gemma oracle
//
// Note: do not name a payload field `len` — `len` is reserved in the Contract for the
// form `len(x) > 0` (the size field is therefore called `size` here).
// =============================================================================
protocol Summarize {
  roles U, S, G;
  agent S caps { read(doc) scope "doc:readonly" mode read ttl 2 sig "s1"; }

  U -> S : Ask(text: Str, budget: Int);
  rec Loop {
    S -> G : Summary(size: Int) [size <= budget] uses read oracle;
    choice at G -> U {
      Ok: { G -> S : Take(); }
      Trim(why: Str) [len(why) > 0]: { G -> S : Again(); continue Loop; }
    }
  }
}

// =============================================================================
// travel_booking.casl — travel booking: ONE approval gates TWO irreversible effects
// =============================================================================
// U = User, S = assistant (agent/ORACLE), F = flight connector, H = hotel connector.
//
// S researches (search, mode read) and proposes a trip with a total cost;
// the data Contract [cost <= budget] MUST hold. In the consent branch of ONE
// approval gate lie TWO irreversible bookings (flight + hotel). Mergeability:
// F and H each receive in BOTH branches a distinguishing label, U gets
// the confirmations — so the 4-role choreography is realizable.
//
//   ./casl check examples/travel_booking.casl
//   ./casl run   examples/travel_booking.casl --approve
// =============================================================================
protocol TravelBooking {
  roles U, S, F, H;
  agent S caps {
    search(query) scope "web:readonly" mode read  ttl 1 sig "s0";
    flight(seg)   scope "air:book"     mode write ttl 1 sig "s1";
    hotel(room)   scope "hotel:book"   mode write ttl 1 sig "s2";
  }

  U -> S : Trip(dest: Str, budget: Int);
  S -> U : Plan(cost: Int) [cost <= budget] uses search oracle;
  choice approval at U -> S {
    Confirm consent: {
      S -> F : BookFlight() uses flight irreversible;
      S -> H : BookHotel()  uses hotel  irreversible;
      F -> U : Ticket();
      H -> U : Voucher();
    }
    Cancel: {
      S -> F : DropFlight();
      S -> H : DropHotel();
      F -> U : Released();
      H -> U : Stood();
    }
  }
}

protocol BadEffect {
  roles S, U;
  agent S caps { mail(to) scope "smtp" mode write ttl 1 sig "s"; }
  S -> U : Send() uses mail irreversible;
}

protocol BadPipe {
  roles A, J;
  A -> J : Draft(x: Int) oracle;
}

protocol BadLin {
  roles A, J;
  choice at A -> J {
    Hit: { A -> J : Out(x: Int) [x <= 100] oracle; }
    Miss: { A -> J : Done(); }
  }
}

protocol GoodStream {
  roles Env, S, U;
  env Env;
  stream Loop {
    choice at Env -> S {
      Ev: { S -> U : Notice(); continue Loop; }
      Quit: { S -> U : Bye(); }
    }
  }
}

protocol BadTerm {
  roles C, A, J;
  rec Loop {
    A -> J : Draft(x: Int);
    choice at J -> C {
      Accept: { J -> A : Done(); }
      Reject: { J -> A : Retry(); continue Loop; }
    }
  }
}

protocol BadCrash {
  roles S, X;
  crash S;
  S -> X : Result();
}

protocol BadTtl {
  roles A, J;
  agent A caps { search(q) scope "web" mode read ttl 2 sig "s"; }
  rec Loop measure n bound 5 {
    A -> J : Draft(x: Int) uses search;
    J -> A : Ack();
    continue Loop;
  }
}

protocol GoodConc {
  roles A, B, C, D;
  A -> B : m();
  C -> D : n();
}

protocol BadConc {
  roles P, Q, R, S;
  P -> Q : a();
  rec t {
    R -> S : b();
    continue t;
  }
}
